style.css:
@-moz-document domain("youtube.com") {
/* === NỀN VÀ LAYOUT === */
  html, body,
  ytd-app,
  #page-manager,
  ytd-browse,
  ytd-watch-flexy {
    background-color: #F4EEFF !important;
  }

  /* === MASTHEAD / HEADER === */
  #masthead-container,
  ytd-masthead {
    background-color: #F4EEFF !important;
    box-shadow: 0 1px 0 #A6B1E1 !important;
  }

  /* === SEARCH BAR === */
  #search-form,
  ytd-searchbox,
  #search {
    background-color: #DCD6F7 !important;
  }
  #search-input,
  ytd-searchbox #search-input {
    background-color: #DCD6F7 !important;
    color: #1a1e40 !important;
  }
  tp-yt-paper-input-container {
    background-color: #DCD6F7 !important;
    border-color: #A6B1E1 !important;
  }
  #search-icon-legacy,
  #search-icon {
    background-color: #A6B1E1 !important;
    border-color: #424874 !important;
  }

  /* === SIDEBAR ĐẦY ĐỦ === */
  #guide-wrapper,
  ytd-guide-renderer,
  tp-yt-app-drawer,
  #contentContainer.ytd-app {
    background-color: #F4EEFF !important;
  }

  ytd-guide-entry-renderer:hover a,
  ytd-guide-section-entry-renderer:hover a {
    background-color: #DCD6F7 !important;
    border-radius: 10px !important;
  }

  ytd-guide-entry-renderer[aria-selected="true"] a,
  ytd-guide-entry-renderer.iron-selected a,
  ytd-guide-entry-renderer[active] a,
  ytd-guide-entry-renderer[aria-selected="true"],
  ytd-guide-entry-renderer.iron-selected {
    background-color: #A6B1E1 !important;
    border-radius: 10px !important;
  }

  ytd-guide-entry-renderer[aria-selected="true"] yt-icon,
  ytd-guide-entry-renderer[aria-selected="true"] .title,
  ytd-guide-entry-renderer.iron-selected yt-icon,
  ytd-guide-entry-renderer.iron-selected .title {
    color: #1a1e40 !important;
  }

  /* === MINI SIDEBAR (bấm 3 gạch thu lại) === */
  ytd-mini-guide-renderer,
  #mini-guide,
  ytd-mini-guide-renderer #items,
  ytd-mini-guide-entry-renderer,
  ytd-mini-guide-renderer.ytd-app {
    background-color: #F4EEFF !important;
  }

  ytd-mini-guide-entry-renderer:hover {
    background-color: #DCD6F7 !important;
    border-radius: 10px !important;
  }

  ytd-mini-guide-entry-renderer[aria-selected="true"],
  ytd-mini-guide-entry-renderer.iron-selected {
    background-color: #A6B1E1 !important;
    border-radius: 10px !important;
  }

  /* === CHIP FILTER BAR (nền thanh) === */
  #chips-wrapper,
  yt-chip-cloud-renderer,
  ytd-feed-filter-chip-bar-renderer,
  ytd-feed-filter-chip-bar-renderer #chips-wrapper,
  ytd-rich-grid-renderer #header,
  ytd-browse #header-container,
  .ytd-feed-filter-chip-bar-renderer {
    background-color: #F4EEFF !important;
  }

  /* === CHIP FILTER (từng nút) === */
  yt-chip-cloud-chip-renderer,
  ytd-chip-cloud-chip-renderer {
    background-color: #DCD6F7 !important;
    border-color: #A6B1E1 !important;
    border-radius: 20px !important;
  }

  yt-chip-cloud-chip-renderer[selected],
  ytd-chip-cloud-chip-renderer[selected],
  yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"][selected] {
    background-color: #424874 !important;
    color: #F4EEFF !important;
  }

  /* === VIDEO CARDS === */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    background-color: #F4EEFF !important;
  }

  ytd-rich-item-renderer:hover {
    background-color: #DCD6F7 !important;
    border-radius: 10px !important;
  }

  /* === SUBSCRIBE BUTTON === */
  ytd-subscribe-button-renderer button,
  yt-button-shape[subscribe] button {
    background-color: #424874 !important;
    color: #F4EEFF !important;
    border-radius: 20px !important;
  }

  /* === VIDEO PLAYER: THANH TIẾN TRÌNH === */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background-color: #424874 !important;
  }
  .ytp-load-progress {
    background-color: #A6B1E1 !important;
  }

  /* === COMMENT SECTION === */
  ytd-comments,
  ytd-comment-thread-renderer,
  ytd-comment-renderer {
    background-color: #F4EEFF !important;
  }

  /* === POPUP / DROPDOWN === */
  tp-yt-paper-dialog,
  tp-yt-iron-dropdown,
  ytd-popup-container,
  yt-dropdown-menu {
    background-color: #DCD6F7 !important;
    border: 1px solid #A6B1E1 !important;
  }

  /* === SCROLLBAR === */
  ::-webkit-scrollbar {
    width: 6px;
    background: #F4EEFF;
  }
  ::-webkit-scrollbar-thumb {
    background: #424874;
    border-radius: 3px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #A6B1E1;
  }
}
